<template>
  <div class="mx-auto max-w-4xl">
    <div class="mb-3 flex items-center gap-2">
      <button class="rounded p-1 text-gray-500 hover:bg-gray-100" @click="$router.back()">←</button>
      <h2 class="text-lg font-semibold">{{ doctype }} {{ name }}</h2>
      <span class="rounded-full px-2 py-0.5 text-xs" :class="statusClass">{{ statusText }}</span>
      <div class="ml-auto flex flex-wrap gap-2">
        <button class="rounded-md border px-3 py-1.5 text-sm" @click="printDoc">🖨 Print</button>
        <!-- Draft actions: the buttons are the workflow actions this user may take
             right now (Submit / Request Approval / Approve / Reject). Someone with no
             available action (e.g. the creator of a below-cost doc awaiting approval)
             sees only a note. -->
        <template v-if="doc.docstatus === 0">
          <button v-if="editable && perms.can_write" class="rounded-md border px-3 py-1.5 text-sm" @click="editing = true">Edit</button>
          <button v-for="a in actions" :key="a.action" :disabled="busy"
            class="rounded-md px-3 py-1.5 text-sm text-white"
            :class="a.action === 'Reject' ? 'bg-red-500 hover:bg-red-600' : 'azzir-brand'"
            @click="doAction(a.action)">{{ a.action }}</button>
          <span v-if="!actions.length" class="self-center text-xs text-gray-500">Awaiting approval</span>
        </template>
        <!-- Submitted: create next in the flow (only the ones this user may create) + Cancel -->
        <template v-else-if="doc.docstatus === 1">
          <button v-for="a in nextActions" :key="a.target" v-show="creatable[a.target] !== false" :disabled="busy" class="azzir-brand rounded-md px-3 py-1.5 text-sm text-white" @click="createNext(a.target)">
            + {{ a.label }}
          </button>
          <button v-if="perms.can_cancel" :disabled="busy" class="rounded-md border border-red-300 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50" @click="cancelDoc">Cancel</button>
        </template>
        <!-- Cancelled: amend (create a new editable draft) -->
        <template v-else-if="doc.docstatus === 2">
          <button v-if="perms.can_amend" :disabled="busy" class="azzir-brand rounded-md px-3 py-1.5 text-sm text-white" @click="amendDoc">Amend</button>
        </template>
      </div>
    </div>

    <div v-if="msg" class="mb-3 rounded-md px-3 py-2 text-sm" :class="err ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'">{{ msg }}</div>
    <div v-if="doc.docstatus === 1 && blockedNext.length" class="mb-3 rounded-md bg-amber-50 px-3 py-2 text-sm text-amber-700">
      You don't have permission to create {{ blockedNext.map((a) => a.label).join(', ') }}. Please ask your manager for access.
    </div>

    <div v-if="loading" class="py-10 text-center text-gray-400">Loading…</div>
    <template v-else>
      <div class="mb-4 grid grid-cols-2 gap-4 rounded-lg border bg-white p-4 text-sm md:grid-cols-4">
        <div><div class="text-xs text-gray-500">Customer</div><div class="font-medium">{{ doc.customer_name || doc.party_name || doc.customer }}</div></div>
        <div><div class="text-xs text-gray-500">Date</div><div>{{ doc.transaction_date || doc.posting_date }}</div></div>
        <div><div class="text-xs text-gray-500">Company</div><div>{{ doc.company }}</div></div>
        <div><div class="text-xs text-gray-500">Grand Total</div><div class="font-semibold">{{ fmt(doc.grand_total, doc.currency) }}</div></div>
      </div>

      <div class="overflow-x-auto rounded-lg border bg-white">
        <table class="min-w-full text-sm">
          <thead class="bg-gray-50 text-left text-gray-500">
            <tr><th class="px-3 py-2">Item</th><th class="px-3 py-2">Qty</th><th class="px-3 py-2">Description</th><th class="px-3 py-2">Rate</th><th class="px-3 py-2">Warehouse</th><th class="px-3 py-2 text-right">Amount</th></tr>
          </thead>
          <tbody>
            <tr v-for="r in doc.items || []" :key="r.name" class="border-t">
              <td class="px-3 py-2"><div class="font-medium">{{ r.item_code }}</div><div class="text-xs text-gray-500">{{ r.item_name }}</div></td>
              <td class="px-3 py-2">{{ r.qty }}</td>
              <td class="px-3 py-2 text-gray-500 max-w-xs truncate" v-html="r.description"></td>
              <td class="px-3 py-2">{{ fmt(r.rate) }}</td>
              <td class="px-3 py-2">{{ r.warehouse || '—' }}</td>
              <td class="px-3 py-2 text-right">{{ fmt(r.amount) }}</td>
            </tr>
          </tbody>
          <tfoot><tr class="border-t"><td colspan="5" class="px-3 py-2 text-right font-semibold">Grand Total</td><td class="px-3 py-2 text-right font-semibold">{{ fmt(doc.grand_total, doc.currency) }}</td></tr></tfoot>
        </table>
      </div>
    </template>

    <DocDialog v-if="editing" :doctype="doctype" :edit="doc" @close="editing = false" @saved="onEdited" />
    <DocDialog v-if="createTarget" :doctype="createTarget" :initial="createInitial" @close="createTarget = null" @saved="onNextSaved" />
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { getDoc, workflowActions, applyWorkflowAction, makeNext, canCreateDoc, actionPerms, cancelSalesDoc, amendSalesDoc, fmt } from '@/utils/api.js'
import DocDialog from '@/components/DocDialog.vue'

const props = defineProps({ doctype: String, name: String })
const router = useRouter()

const doc = ref({})
const loading = ref(true)
const busy = ref(false)
const editing = ref(false)
const createTarget = ref(null)
const createInitial = ref(null)
const msg = ref('')
const err = ref(false)
const actions = ref([]) // workflow actions available to THIS user on this doc
// Edit / Cancel / Amend permissions on this doc (ERPNext role permissions).
const perms = ref({})

// A doc awaiting approval isn't editable by the creator (the workflow's Pending state
// only allows the approver to edit), so hide Edit then.
const editable = computed(() => doc.value.docstatus === 0 && !/pending/i.test(doc.value.workflow_state || ''))

const statusText = computed(() => doc.value.workflow_state || doc.value.status || (doc.value.docstatus === 1 ? 'Submitted' : doc.value.docstatus === 2 ? 'Cancelled' : 'Draft'))
const statusClass = computed(() => doc.value.docstatus === 1 ? 'bg-green-100 text-green-700' : doc.value.docstatus === 2 ? 'bg-red-100 text-red-700' : /pending/i.test(doc.value.workflow_state || '') ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-600')

const SPA_ROUTE = { Quotation: '/quotations', 'Sales Invoice': '/invoices', 'Delivery Note': '/delivery-notes' }
const nextActions = computed(() => {
  if (props.doctype === 'Quotation') return [{ target: 'Sales Invoice', label: 'Sales Invoice' }]
  if (props.doctype === 'Sales Invoice') {
    const acts = [{ target: 'Delivery Note', label: 'Delivery Note' }, { target: 'Payment Entry', label: 'Payment Entry' }]
    // Credit Note = a return of THIS invoice (needs Sales Invoice create perm). Not on a
    // credit note itself, and only on a submitted invoice.
    if (!doc.value.is_return && doc.value.docstatus === 1) acts.push({ target: 'Credit Note', label: 'Credit Note', perm: 'Sales Invoice' })
    return acts
  }
  return []
})
// Per-target create permission (false = not allowed) — gates the buttons and drives
// the "ask your manager" note. Loaded once the submitted doc is shown.
const creatable = ref({})
const blockedNext = computed(() => nextActions.value.filter((a) => creatable.value[a.target] === false))
async function loadCreatePerms() {
  const entries = await Promise.all(
    nextActions.value.map(async (a) => [a.target, await canCreateDoc(a.perm || a.target).catch(() => false)]),
  )
  creatable.value = Object.fromEntries(entries)
}

async function load() {
  loading.value = true
  try {
    doc.value = await getDoc(props.doctype, props.name)
    actions.value = doc.value.docstatus === 0
      ? ((await workflowActions(props.doctype, props.name).catch(() => ({}))).actions || [])
      : []
    perms.value = await actionPerms(props.doctype, props.name).catch(() => ({}))
    if (doc.value.docstatus === 1) await loadCreatePerms()
  } finally { loading.value = false }
}
onMounted(load)

// Cancel a submitted document (permission enforced server-side).
async function cancelDoc() {
  if (!window.confirm(`Cancel ${props.doctype} ${props.name}? This cannot be undone.`)) return
  busy.value = true; msg.value = ''
  try {
    await cancelSalesDoc(props.doctype, props.name)
    err.value = false; msg.value = 'Cancelled.'
    await load()
  } catch (e) { err.value = true; msg.value = e?.messages?.join(', ') || e?.message || 'Could not cancel.' }
  finally { busy.value = false }
}

// Amend a cancelled document: create a new draft and open it.
async function amendDoc() {
  busy.value = true; msg.value = ''
  try {
    const r = await amendSalesDoc(props.doctype, props.name)
    err.value = false
    const route = SPA_ROUTE[props.doctype]
    if (route && r?.name) router.push(`${route}/${encodeURIComponent(r.name)}`)
  } catch (e) { err.value = true; msg.value = e?.messages?.join(', ') || e?.message || 'Could not amend.' }
  finally { busy.value = false }
}

// Apply the chosen workflow action (Submit / Request Approval / Approve / Reject).
// Role + self-approval are enforced server-side by the workflow engine.
async function doAction(action) {
  busy.value = true; msg.value = ''
  try {
    const res = await applyWorkflowAction(props.doctype, props.name, action)
    err.value = false
    msg.value = res.docstatus === 1 ? 'Approved & submitted.' : (res.workflow_state ? `Moved to ${res.workflow_state}.` : 'Done.')
    await load()
  } catch (e) { err.value = true; msg.value = e?.messages?.join(', ') || e?.message || 'Could not complete the action.' }
  finally { busy.value = false }
}
function onEdited() { editing.value = false; load() }

async function createNext(target) {
  if (busy.value) return  // guard against a fast double-click creating the next doc twice
  if (creatable.value[target] === false) {
    err.value = true
    msg.value = `You don't have permission to create a ${target}. Please ask your manager for access.`
    return
  }
  busy.value = true; msg.value = ''
  try {
    const r = await makeNext(props.doctype, props.name, target)
    err.value = false
    if (r.mode === 'open') {
      if (r.spa && SPA_ROUTE[r.doctype]) {
        // Credit Note: a return created straight away — open it here in the app to review
        // and send for approval.
        router.push(`${SPA_ROUTE[r.doctype]}/${encodeURIComponent(r.name)}`)
        msg.value = `${target} created — review and send for approval.`
      } else {
        // Payment Entry: created straight away, open it in the desk.
        window.open(`/app/${r.doctype.toLowerCase().replace(/ /g, '-')}/${encodeURIComponent(r.name)}`, '_blank')
        msg.value = `${r.doctype} created — opened in a new tab.`
      }
    } else {
      // Sales Invoice / Delivery Note: review the prefilled form, then save.
      createTarget.value = r.doctype
      createInitial.value = r.data
    }
  } catch (e) {
    err.value = true; msg.value = e?.messages?.join(', ') || e?.message || `Could not create ${target}.`
  } finally { busy.value = false }
}

function printDoc() {
  // Opens the desk print view, which renders the doctype's default print format.
  const url = `/printview?doctype=${encodeURIComponent(props.doctype)}&name=${encodeURIComponent(props.name)}&trigger_print=1`
  window.open(url, '_blank')
}

function onNextSaved(saved) {
  const target = createTarget.value
  createTarget.value = null
  const route = SPA_ROUTE[target]
  if (route && saved?.name) router.push(`${route}/${encodeURIComponent(saved.name)}`)
}
</script>
